sys_ux_data_broker_transform.props:
[
{
  "name": "userId",
  "label": "User",
  "description": "Input for the current logged in user id",
  "readOnly": false,
  "fieldType": "string",
  "mandatory": true
}
]

sys_ux_data_broker_transform.script:
function transform(input) {
    var userId = input.userId;
    var userInfoPayload = {};
    var designation = "",
        pod = "",
        dl = "",
        coach = "",
        project = [],
        contact = "",
        email = "",
        emailLogs = [],
		birthAnnivDue = "",
		workAnnivDue = "";
    var grMemberObj = new GlideRecord("sys_user_grmember");
    grMemberObj.addEncodedQuery("user=" + userId);
    grMemberObj.query();
    while (grMemberObj.next()) {
        if (grMemberObj.group.name.includes("GRC") && !grMemberObj.group.name.includes("GRC Internal Ops Team")) {
            designation = (grMemberObj.group == '2248dc31838ee21002d6c3b6feaad322') ? "Senior Manager" : (grMemberObj.group == 'e0b99c71838ee21002d6c3b6feaad36f') ? "Manager" : (grMemberObj.group == '46a81071838ee21002d6c3b6feaad364') ? "Senior Associate" : (grMemberObj.group == '61199cfd834ee21002d6c3b6feaad388') ? "Associate" : (grMemberObj.group == 'f345287183cee21002d6c3b6feaad366') ? "Intern" : "N/A";
            designation = (grMemberObj.group == 'ece2972d830ae21002d6c3b6feaad3d2') ? "Security Admin" : (grMemberObj.group == 'd41257e9830ae21002d6c3b6feaad3de') ? "Admin" : designation;
        }
        if (grMemberObj.group.name.includes("POD")) {
            pod = (grMemberObj.group == '9fa0200a8382661002d6c3b6feaad382') ? "POD 1" : (grMemberObj.group == '9d51e40a8382661002d6c3b6feaad3b9') ? "POD 2" : (grMemberObj.group == '88716cc68382661002d6c3b6feaad3bd') ? "POD 3" : (grMemberObj.group == '4ff338d58352665002d6c3b6feaad342') ? "POD 4" : (grMemberObj.group == '3f14f09d8352665002d6c3b6feaad3b3') ? "POD 5" : (grMemberObj.group == '1634b4d58352665002d6c3b6feaad354') ? "POD 6" : "N/A";
        }
    }

    var grUserObj = new GlideRecord("sys_user");
    if (grUserObj.get(userId)) {
        dl = grUserObj.getDisplayValue('u_dev_leader');
        coach = grUserObj.getDisplayValue('u_coach');
        contact = grUserObj.getValue('mobile_phone');
        email = grUserObj.getValue('email');
        var birthDate = grUserObj.getValue('u_bday');
        var joinDate = grUserObj.getValue('u_glide_date_5');
		var scriptCallObj = new x_1324635_grc_ops.GRCOpsUtils();
		birthAnnivDue = scriptCallObj.anniversaryDaysDueCalculation(birthDate);
		workAnnivDue = scriptCallObj.anniversaryDaysDueCalculation(joinDate);
    }

    var grProjectObj = new GlideRecord("x_1324635_grc_ops_project_allocation");
    grProjectObj.addEncodedQuery("assigned_toLIKE" + userId);
    grProjectObj.query();
    while (grProjectObj.next()) {
        project.push(grProjectObj.getValue('project_name'));
    }

    var grEmailObj = new GlideRecord("sys_email");
    grEmailObj.addEncodedQuery("recipientsLIKE" + email);
    grEmailObj.orderByDesc('sys_created_on');
    grEmailObj.setLimit(10);
    grEmailObj.query();
    while (grEmailObj.next()) {
        emailLogs.push({
            "id": grEmailObj.getUniqueValue(),
            "label": grEmailObj.getValue('subject'),
            "sublabel": grEmailObj.getValue("sys_created_on")
        });
    }


    userInfoPayload["designation"] = designation || "N/A";
    userInfoPayload["pod"] = pod || "Not in POD";
    userInfoPayload["dl"] = dl || "N/A";
    userInfoPayload["coach"] = coach || "N/A";
    userInfoPayload["project"] = project.join(", ") || "N/A";
    userInfoPayload["contact"] = contact || "N/A";
    userInfoPayload["email"] = email || "N/A";
    userInfoPayload["timestamp"] = new GlideDateTime();
    userInfoPayload["emailLogs"] = JSON.stringify(emailLogs);
	userInfoPayload["birthAnnivDue"] = birthAnnivDue;
	userInfoPayload["workAnnivDue"] = workAnnivDue;

    return JSON.stringify(userInfoPayload);
}
